import com.hopeless.infinity.planet.*; import java.util.*;
/** MetroRoadsProbe: 0.27.7 how the road network meets each megacity on seed 1 (planet/Metro, planet/Roads), measured from the laid
 *  roads' own samples: where each road ends against the plan's centre and its boulevard, the step between the road's end height and the
 *  boulevard's pad there, road samples on tower lots, and the boulevard's steepest step. Saved tool (MetroRoadsTest reuses run()). */
public class MetroRoadsProbe {
  static double arc(double[] a, double[] b) { double d = a[0] * b[0] + a[1] * b[1] + a[2] * b[2], la = Math.sqrt(a[0]*a[0]+a[1]*a[1]+a[2]*a[2]), lb = Math.sqrt(b[0]*b[0]+b[1]*b[1]+b[2]*b[2]); return Math.acos(Math.max(-1, Math.min(1, d / (la * lb)))); }
  /** per city: {roads, worst end from the plan centre (m), worst |end height - boulevard pad| (blocks), samples on tower lots, boulevard steepest grade, ends off a boulevard end (> 20 m)} */
  public static Map<String, double[]> run(PlanetWorld w, boolean print) {
    Metro m = w.metro(); Roads r = w.roads(); double R = w.cube.R; Map<String, double[]> out = new LinkedHashMap<>();
    // 0.28.2 the megacities and the 5 largest large cities (laying every road of all 149 large cities would take minutes)
    List<Sites.Site> lc = new ArrayList<>(); for (Sites.Site s : w.sites().all) if (s.kind == Sites.Kind.LARGE_CITY && Metro.isCity(s)) lc.add(s); lc.sort((x, y) -> Long.compare(y.pop, x.pop)); Set<Integer> pick = new HashSet<>(); for (int i = 0; i < Math.min(5, lc.size()); i++) pick.add(lc.get(i).id);
    for (Metro.Plan p : m.plans.values()) { if (p.blvdY == null) continue; if (p.site.kind != Sites.Kind.MEGACITY && !pick.contains(p.site.id)) continue; double[] c = w.cube.spherePoint(p.face, p.cx, p.cz); double[] e0 = sphereOf(w, p, 0, -p.blvdHalf), e1 = sphereOf(w, p, 0, p.blvdHalf);
      int roads = 0, onLot = 0, offEnd = 0, lotsEnds = 0; double worstEnd = 0, worstStep = 0; long t0 = System.nanoTime();
      for (Roads.Edge e : r.edges) { if ((e.a != p.site.id && e.b != p.site.id) || e.cls == Roads.Cls.RAIL) continue;   /* 0.29.0 rail ends at its yard (RailTest) */ roads++; Roads.Route ro = r.route(e.id); int i = e.a == p.site.id ? 0 : ro.n() - 1; double[] q = ro.p(i);
        worstEnd = Math.max(worstEnd, arc(q, c) * R); double dEnd = 1e9; boolean atBlvd = false; for (double[] pt : p.portals) { double[] ps = sphereOf(w, p, pt[0], pt[1]); if (ps == null) continue; double dd = arc(q, ps) * R; if (dd < dEnd) { dEnd = dd; atBlvd = pt[2] == 0; } } if (dEnd > 20 || (e.cls == Roads.Cls.INTERSTATE && !atBlvd)) offEnd++; if (!atBlvd) lotsEnds++;
        double[] fx = w.cube.locate(q); if (atBlvd && (int) fx[0] == p.face) { double[] uv = p.uv(fx[1], fx[2]); int pad = m.blvdPad(p, uv[0], Math.max(-p.blvdHalf, Math.min(p.blvdHalf, uv[1]))); int ry = (int) Math.floor(Terrain.toYd(ro.z[i])) + 1; worstStep = Math.max(worstStep, Math.abs(ry - pad)); if (print && Math.abs(ry - pad) > 2) System.out.printf("    step: %s %d (%s) end y %d, boulevard pad %d at v %.0f; road z %.1f, ground %.1f, kind %d, hold miss %d cm%n", e.cls, e.id, i == 0 ? "start" : "end", ry, pad, uv[1], ro.z[i], ro.ground[i], ro.kind[i], ro.holdMissCm); }
        for (int k = 0; k < ro.n(); k += 2) { double[] s = ro.p(k); if (arc(s, c) * R > p.reachM * 1.5) continue; double[] f2 = w.cube.locate(s); if ((int) f2[0] != p.face) continue; int[] at = m.at(p.face, (int) Math.floor(f2[1]), (int) Math.floor(f2[2]), s); if (at != null && at[1] == 1 && ro.kind[k] != 1) { onLot++; if (print && onLot % 40 == 1) { double[] uv = p.uv(f2[1], f2[2]); System.out.printf("    on a lot: %s %d at %.0f of %.0f m (plan u %.0f, v %.0f), end at %s%n", e.cls, e.id, ro.along[k], ro.along[ro.n() - 1], uv[0], uv[1], e.a == p.site.id ? "start" : "end"); } } } }
      int shared = 0, parallel = 0; { java.util.List<double[]> pts = new ArrayList<>(); for (Roads.Edge e : r.edges) { if ((e.a != p.site.id && e.b != p.site.id) || e.cls == Roads.Cls.RAIL) continue;   /* 0.29.0 rail ends at its yard (RailTest) */ Roads.Route ro = r.route(e.id); for (int k = 0; k < ro.n(); k += 2) { double[] q = ro.p(k); if (arc(q, c) * R < p.reachM + Metro.LEAD_M + 300) { double[] q2 = ro.p(Math.min(ro.n() - 1, k + 1)), q0 = ro.p(Math.max(0, k - 1)); pts.add(new double[]{q[0], q[1], q[2], e.id, ro.z[k], e.cls == Roads.Cls.INTERSTATE ? 1 : 0, q2[0] - q0[0], q2[1] - q0[1], q2[2] - q0[2]}); } } }
        // per pair (an Interstate and another road): the closest pair of samples; a crossing at grade when they come within 10 m across at under 5 m in height, at 25 deg or more
        Map<String, double[]> pair = new TreeMap<>(); for (double[] q : pts) for (double[] o : pts) { if (o[3] <= q[3] || (o[5] + q[5]) != 1) continue; double d = arc(q, o) * R; if (d > 20) continue; String k = (int) q[3] + "/" + (int) o[3];
            double cs = Math.abs(q[6] * o[6] + q[7] * o[7] + q[8] * o[8]) / Math.max(1e-12, Math.sqrt((q[6] * q[6] + q[7] * q[7] + q[8] * q[8]) * (o[6] * o[6] + o[7] * o[7] + o[8] * o[8])));
            double[] cur = pair.get(k); if (cur == null || d < cur[0]) pair.put(k, new double[]{d, Math.abs(q[4] - o[4]), Math.toDegrees(Math.acos(Math.min(1, cs))), arc(q, c) * R}); }
        for (var en : pair.entrySet()) { double[] v = en.getValue(); if (v[0] > 10 || v[1] >= 5) continue; if (v[2] < 25) parallel++; else { shared++; if (print) System.out.printf("    at grade: roads %s, %.1f m apart, %.1f m in height, at %.0f deg, %.0f m from the centre%n", en.getKey(), v[0], v[1], v[2], v[3]); } } }      double mg = 0; { int prev = m.blvdPad(p, -p.blvdHalf); for (double v = -p.blvdHalf + 64; v <= p.blvdHalf; v += 64) { int y = m.blvdPad(p, v); mg = Math.max(mg, Math.abs(y - prev) / 64.0); prev = y; } }   /* over 64 m: a 1-block step every 16 m is 6.25 % */
      // 0.27.8 the streets: steepest avenue over 64 m (only where Metro.at says avenue), steps at the avenue portals and at the boulevard
      double sg = 0, aStep = 0, bStep = 0; int aveCols = 0; long ts = System.nanoTime(); m.streetPad(p, 0, 0); double fieldMs = (System.nanoTime() - ts) / 1e6;
      for (int dir = 0; dir < 2; dir++) for (int j = -40; j < 40; j++) { double line = (j + 0.5) * Metro.PITCH_M; if (Math.abs(line) > p.reachM) continue; int prev = Integer.MIN_VALUE;
        for (double a2 = -p.reachM; a2 <= p.reachM; a2 += 64) { double u = dir == 0 ? a2 : line, v = dir == 0 ? line : a2; double[] xz = p.xz(u, v); double[] sp = w.cube.spherePoint(p.face, xz[0], xz[1]); if (sp == null) { prev = Integer.MIN_VALUE; continue; }
          int[] at = m.at(p.face, (int) Math.floor(xz[0]), (int) Math.floor(xz[1]), sp); if (at == null || at[1] != 4) { prev = Integer.MIN_VALUE; continue; } aveCols++; if (prev != Integer.MIN_VALUE) sg = Math.max(sg, Math.abs(at[0] - prev) / 64.0); prev = at[0]; } }
      for (int k = 0; k < p.portals.size(); k++) { double[] pt = p.portals.get(k); if (pt[2] == 0) continue; double inU = pt[2] == 1 ? -pt[3] * 3 : 0, inV = pt[2] == 2 ? -pt[3] * 3 : 0; int sp = m.streetPad(p, pt[0] + inU, pt[1] + inV);
        for (Roads.Edge e : r.edges) { if ((e.a != p.site.id && e.b != p.site.id) || e.cls == Roads.Cls.RAIL) continue;   /* 0.29.0 rail ends at its yard (RailTest) */ double[] q = e.a == p.site.id ? e.pts[0] : e.pts[e.pts.length - 1]; double[] ps = sphereOf(w, p, pt[0], pt[1]); if (ps == null || arc(q, ps) * R > 30) continue; Roads.Route ro = r.route(e.id); int i = e.a == p.site.id ? 0 : ro.n() - 1; int st2 = Math.abs((int) Math.floor(Terrain.toYd(ro.z[i])) + 1 - sp); aStep = Math.max(aStep, st2); if (print && st2 > 1) System.out.printf("    avenue portal %d (u %.0f, v %.0f, kind %.0f): road %s %d end z %.1f, street pad %d (road y %d)%n", k, pt[0], pt[1], pt[2], e.cls, e.id, ro.z[i], sp, (int) Math.floor(Terrain.toYd(ro.z[i])) + 1); } }
      for (int j = -40; j < 40; j++) { double v = (j + 0.5) * Metro.PITCH_M; if (Math.abs(v) > p.blvdHalf) continue; if (!m.onAvenue(p, Metro.BOULEVARD_M / 2 + 2, v)) continue; bStep = Math.max(bStep, Math.max(Math.abs(m.streetPad(p, Metro.BOULEVARD_M / 2 + 1, v) - m.blvdPad(p, v)), Math.abs(m.streetPad(p, -Metro.BOULEVARD_M / 2 - 1, v) - m.blvdPad(p, v)))); }
      if (print) System.out.printf("    streets: %d avenue samples, steepest %.1f %% over 64 m; step at avenue portals %.0f, at the boulevard %.0f blocks; field %d ms (%d passes)%n", aveCols, sg * 100, aStep, bStep, p.streetMs, p.streetPasses);
      out.put(p.site.name, new double[]{roads, worstEnd, worstStep, onLot, mg, offEnd, lotsEnds, shared, sg, aStep, bStep, aveCols, parallel});
      if (print) System.out.printf("  %-16s boulevard %.1f km (steepest %.1f %%): %d roads, every end %s its portal, Interstates on the boulevard (%d off; %d at avenue ends), ends up to %.1f km from the centre, end step up to %.0f blocks, %d road samples on tower lots, %d places where an Interstate crosses another road at grade, %d road pairs sharing a corridor (under 25 deg: merged at the junction stage, not built yet) (%.0f ms)%s%n",
        p.site.name, 2 * p.blvdHalf / 1000, mg * 100, roads, offEnd == 0 ? "at" : "NOT at", offEnd, lotsEnds, worstEnd / 1000, worstStep, onLot, shared, parallel, (System.nanoTime() - t0) / 1e6, w.spawnKind.contains(p.site.name) ? "  [SPAWN]" : ""); }
    return out; }
  static double[] sphereOf(PlanetWorld w, Metro.Plan p, double u, double v) { double[] xz = p.xz(u, v); return w.cube.spherePoint(p.face, xz[0], xz[1]); }
  public static void main(String[] a) { PlanetWorld w = new PlanetWorld(1); w.playerSpawn(); for (Sites.Site s : w.sites().all) if (s.kind == Sites.Kind.MEGACITY && (a.length == 0 || s.name.startsWith(a[0]))) w.metro().plan(s); run(w, true); } }
